dialog{color:var(--ink);background:#fff;border:1px solid var(--line);border-radius:6px;padding:24px;max-height:88vh}dialog::backdrop{background:rgba(16,30,22,.48)}.dialog-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.dialog-head h2{font-size:19px;margin:0}.dialog-head button{font-size:12px}#search-dialog{width:min(640px,94vw)}dialog label{font-size:13px}input{padding:10px 12px;border:1px solid #cbd5cf;border-radius:4px;background:white;color:var(--ink);min-width:0}#search-input{width:100%;margin-top:8px}#search-count{font-size:12px;color:var(--muted)}#search-results{list-style:none;padding:0;max-height:48vh;overflow:auto}#search-results a{display:block;text-decoration:none;padding:10px 12px;border-radius:4px}#search-results a:hover{background:var(--soft)}#search-results small{display:block;color:var(--muted);font-size:11px}
