/* The native disclosure keeps language switching available without JavaScript. */
.language-selector { position: relative; font-size: 14px; margin: 0; padding: 0; align-self: center; }
.language-selector summary { cursor: pointer; padding: .4rem .65rem; white-space: nowrap; }
.language-selector nav { position: absolute; right: 0; top: 100%; min-width: 130px; padding: .4rem; background: white; border: 1px solid #cbd8d2; border-radius: 6px; z-index: 50; box-shadow: 0 4px 12px #17201e18; }
.language-selector nav a { display: block; padding: .4rem .65rem; }
.language-selector [aria-current] { font-weight: 700; background: #edf5f1; }
.translation-note { font-size: 13px; color: #52635c; border-left: 3px solid #8ba99e; padding-left: 12px; }
@media(max-width:760px){.site-header{height:auto;min-height:60px;flex-wrap:wrap;padding:10px 18px;gap:8px}.brand{flex:1 1 100%}.header-actions{margin-left:auto}.language-selector{font-size:12px}}
/* Glossary terms: folded per-page list, underlined first use in the text and an in-place meaning box. */
details.page-terms{margin:18px 0 26px;padding:10px 14px;background:var(--soft);font-size:14px}details.page-terms summary{font-weight:600;color:#33433c}details.page-terms[open] summary{margin-bottom:8px}
button.term{display:inline;font:inherit;color:inherit;background:none;border:0;border-radius:0;padding:0;margin:0;cursor:help;text-decoration:underline dotted #6f8b80;text-decoration-thickness:1.5px;text-underline-offset:4px}button.term:hover,button.term[aria-expanded=true]{background:#edf5f1;text-decoration-color:var(--accent)}
#term-popover{position:absolute;z-index:40;background:#fff;border:1px solid #cbd8d2;border-radius:6px;padding:12px 15px;box-shadow:0 8px 22px #17201e26;font-size:14px;line-height:1.7}#term-popover p{margin:4px 0 8px}#term-popover a{font-size:13px}
@media print{button.term{text-decoration:none}#term-popover{display:none}}

/* Reader navigation is a short choice table, including on narrow screens. */
.reading-routes table{min-width:0;table-layout:fixed}.reading-routes td:first-child{min-width:0}.reading-routes th,.reading-routes td{overflow-wrap:anywhere}

/* Phones read tables of three or more columns as one labelled block per row, without sideways scrolling. */
@media screen and (max-width:760px){.table-scroll.stack{overflow:visible}.stack thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.stack table,.stack tbody,.stack tr,.stack td{display:block;width:auto;min-width:0}.stack tr{border:1px solid var(--line);border-radius:6px;padding:4px 14px;margin:0 0 12px}
.stack td,.stack td:first-child{border:0;padding:7px 0;min-width:0;overflow-wrap:anywhere}.stack td+td{border-top:1px solid var(--line)}
.stack td::before{content:attr(data-label);display:block;font-size:11px;font-weight:650;color:var(--muted);line-height:1.5;margin-bottom:2px}.stack td[data-label=""]::before{content:none}}

/* Page state badges are short words; the exact record stays in the page evidence. */
/* Three visible levels: audience, task, then document. */
.nav-section{margin:0 0 18px 3px;padding-left:9px;border-left:1px solid var(--line)}
.nav-section>h2{font-size:11px;font-weight:650;line-height:1.6;letter-spacing:.02em;margin:0 0 5px 11px;color:var(--muted)}
#sidebar .nav-section>a{margin-left:0}
.state-help{font-size:12px;color:var(--muted)}.state-help:hover{color:var(--accent)}

/* Evidence belongs to the preceding paragraph; native disclosure works offline. */
details.source-excerpts{margin:16px 0;overflow-wrap:anywhere}.source-excerpts>details{margin:12px 0}.source-excerpts>summary{min-height:28px}
details.evidence-links{border:0;border-left:2px solid var(--line);border-radius:0;padding:0 12px;margin:-7px 0 20px;font-size:12px;color:var(--muted)}
.evidence-links>summary{font-weight:400;padding:4px 0;min-height:28px;width:fit-content}
.evidence-links>summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.evidence-links ul{list-style:none;padding:0;margin:8px 0 12px}.evidence-links li{margin:8px 0;overflow-wrap:anywhere}
.evidence-links li>code{background:none;padding:0;color:var(--ink)}.evidence-lines{display:block;line-height:2.1}
.evidence-lines a{display:inline-block;margin-right:4px}.evidence-lines a:focus-visible{outline:2px solid var(--accent)}
details.evidence-section{border-top:1px solid var(--line);border-left:0;margin:8px 0 24px;padding:5px 0 0}

/* Mobile navigation is a viewport drawer; static navigation remains available without scripts. */
.menu-backdrop,.sidebar-close{display:none}
.previous-route:not(:target){display:none}.previous-route{scroll-margin-top:calc(var(--site-header-height,68px) + 16px);padding:12px;border:1px solid var(--line);margin:12px 0}.previous-route p{margin:0 0 4px;font-size:12px;color:var(--muted)}
html.menu-open,html.menu-open body{overflow:hidden}
.evidence-return{position:sticky;top:calc(var(--site-header-height,68px) + 8px);z-index:2;margin:10px 0;background:#fff}
.index-tools{display:grid;grid-template-columns:minmax(160px,2fr) minmax(130px,1fr) minmax(100px,1fr) auto;gap:12px;align-items:end;padding:16px;margin:20px 0;background:var(--soft);border:1px solid var(--line);border-radius:6px}
.index-tools label{display:grid;gap:4px;min-width:0;font-size:12px}.index-tools :is(input,select){width:100%;min-width:0;font:inherit;font-size:14px;padding:8px;border:1px solid #cbd5cf;border-radius:4px;background:#fff;color:var(--ink)}
.index-tools button{font-size:13px;min-height:40px}.index-tools p{grid-column:1/-1;margin:0;font-size:12px;color:var(--muted)}
tr[id^="symbol-"]:target{background:#edf5f1}tr[id^="symbol-"]{scroll-margin-top:calc(var(--site-header-height,68px) + 16px)}
.diagram-pan-hint{font-size:12px;color:var(--muted);margin:0 0 10px}
@media(max-width:760px){
  body.js #sidebar{position:fixed;top:var(--site-header-height,104px);bottom:0;left:0;width:min(360px,calc(100vw - 36px));height:auto;max-height:calc(100dvh - var(--site-header-height,104px));overflow:auto;overscroll-behavior:contain;z-index:60;background:#fff;border-right:1px solid var(--line);box-shadow:6px 0 24px #17201e26}
  .menu-backdrop{display:block;position:fixed;inset:var(--site-header-height,104px) 0 0;z-index:50;border:0;border-radius:0;background:#17201e70;padding:0}.menu-backdrop:hover{background:#17201e70}
  .sidebar-close{display:block;margin:0 0 18px auto;min-height:44px}
  .index-tools{grid-template-columns:1fr 1fr;padding:12px;gap:10px}.index-tools label:first-child{grid-column:1/-1}.index-tools :is(input,select,button){min-height:44px}
  #diagram-dialog .dialog-head button,.diagram-tools button{min-width:44px;min-height:44px}.diagram-tools input{min-height:44px;flex:1;max-width:100%}.diagram-tools{gap:8px}.diagram-pan-hint{line-height:1.5}
}
@media print{.menu-backdrop,.sidebar-close,.index-tools,.evidence-return{display:none!important}}

